// Generated public app shell; never contains household data.
export default "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<script id=\"ourhouse-bootstrap\">// Start public sign-in configuration while critical scripts download in parallel.\n// No session or family data is read here; failures are handled by auth startup.\n(()=>{const query=new URLSearchParams(location.search);if(window.OurHouseAuth||query.get('test')==='1'||query.get('legacy')==='1')return;window.OurHouseConfigRequest=fetch('/api/config',{credentials:'same-origin',cache:'no-store',signal:AbortSignal.timeout(10000)}).catch(()=>null);})();\n</script>\n<link rel=\"preload\" as=\"script\" href=\"/ourhouse-auth.js?v=2b8d9b6dc336\" fetchpriority=\"high\">\n<link rel=\"preload\" as=\"script\" href=\"/assets/app-core-dd790b030f3c4920.js\" fetchpriority=\"high\">\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n<meta name=\"mobile-web-app-capable\" content=\"yes\">\n<meta name=\"apple-mobile-web-app-status-bar-style\" content=\"default\">\n<meta name=\"apple-mobile-web-app-title\" content=\"OurHouse\">\n<meta name=\"theme-color\" content=\"#EBF2F8\">\n<link rel=\"manifest\" href=\"/manifest.webmanifest\">\n<link rel=\"stylesheet\" href=\"/cover-photo.css?v=98557b87f98d\">\n<link rel=\"stylesheet\" href=\"/dish-editor.css?v=6d56bfc51602\">\n<link rel=\"stylesheet\" href=\"/maintenance.css?v=881645f0c1c3\">\n<link rel=\"stylesheet\" href=\"/user-guide.css?v=b07b88a69ca3\">\n<link rel=\"apple-touch-icon\" sizes=\"180x180\" href=\"/icons/ourhouse-180.png\">\n\n\n\n<noscript></noscript>\n<title>OurHouse · Your household, together</title>\n<link rel=\"icon\" type=\"image/png\" sizes=\"192x192\" href=\"/icons/ourhouse-192.png\">\n<link rel=\"stylesheet\" href=\"/assets/app-3243e5afca76ae3d.css?v=3243e5afca76\">\n<link rel=\"stylesheet\" href=\"/family.css?v=795ab70cda76\">\n<link rel=\"stylesheet\" href=\"/liquid-glass.css?v=e1b26e14408b\">\n<link rel=\"stylesheet\" href=\"/redesign.css?v=4bced79d1b58\"></head>\n<body>\n<input id=\"personalPhotoInput\" type=\"file\" accept=\"image/*\" hidden onchange=\"handlePersonalPhotoSelection(event)\">\n\n<!-- Sign-in gate (cloud mode, shown until authenticated) -->\n<div class=\"signin-screen\" id=\"signinScreen\">\n  <div class=\"semblem\"></div>\n  <h2>Welcome to OurHouse</h2>\n  <p class=\"ios-browser-note\" id=\"iosBrowserNote\" style=\"display:none\">📱 You're in <b id=\"iosBrowserName\">this browser</b> on iPhone. To add this app to your Home Screen properly, please open this link in <b>Safari</b> instead — Apple only allows Chrome, and other iPhone browsers to save it as a regular bookmark, not a full Home Screen app. This isn't something we can fix from the app; it's an Apple restriction.</p>\n  <p>Sign in to sync with your household. New members join as viewers until an admin grants access.</p>\n  <button class=\"btn google pressable\" onclick=\"signInGoogle()\">\n    <svg viewBox=\"0 0 48 48\"><path fill=\"#FFC107\" d=\"M43.6 20.5H42V20H24v8h11.3C33.7 32.9 29.3 36 24 36c-6.6 0-12-5.4-12-12s5.4-12 12-12c3.1 0 5.8 1.1 8 3l6-6C34.5 5.1 29.5 3 24 3 12.4 3 3 12.4 3 24s9.4 21 21 21 21-9.4 21-21c0-1.4-.1-2.4-.4-3.5z\"/><path fill=\"#FF3D00\" d=\"M6.3 14.7l6.6 4.8C14.7 15.9 19 13 24 13c3.1 0 5.8 1.1 8 3l6-6C34.5 5.1 29.5 3 24 3 16.3 3 9.6 7.3 6.3 14.7z\"/><path fill=\"#4CAF50\" d=\"M24 45c5.4 0 10.3-2.1 14-5.5l-6.5-5.5C29.4 35.5 26.8 36.5 24 36.5c-5.3 0-9.7-3.5-11.3-8.3l-6.6 5.1C9.5 40.7 16.2 45 24 45z\"/><path fill=\"#1976D2\" d=\"M43.6 20.5H42V20H24v8h11.3c-.8 2.4-2.3 4.4-4.3 5.9l6.5 5.5C40.9 36.7 45 31.4 45 24c0-1.4-.1-2.4-.4-3.5z\"/></svg>\n    <span>Continue with Google</span>\n  </button>\n\n  <p id=\"googleAuthStatus\" role=\"status\" aria-live=\"polite\" style=\"margin:12px 0 0;display:none\"></p>\n\n  <div class=\"signin-divider\">OR</div>\n\n  <div class=\"email-panel\" id=\"emailPanel\">\n    <input type=\"email\" id=\"authEmail\" placeholder=\"Email address\" inputmode=\"email\" autocomplete=\"email\" autocapitalize=\"off\">\n    <input type=\"password\" id=\"authPassword\" placeholder=\"Password\" autocomplete=\"current-password\">\n    <div class=\"efrow\">\n      <button class=\"btn tint\" style=\"flex:1\" onclick=\"signInEmail()\"><span>Sign in</span></button>\n      <button class=\"btn grey\" style=\"flex:1\" onclick=\"createEmailAccount()\"><span>Create account</span></button>\n    </div>\n    <p class=\"email-errmsg\" id=\"emailErr\"></p>\n  </div>\n  <button class=\"signin-anon\" id=\"emailToggleBtn\" onclick=\"toggleEmailPanel()\"><span data-icon=\"clipboard\" data-icon-size=\"16\"></span>Sign in with email instead</button>\n\n  <button class=\"signin-anon\" onclick=\"signInAnon()\" style=\"margin-top:6px\">Continue without an account</button>\n  <p class=\"signin-note\" id=\"signinNote\" style=\"display:none\">Google sign-in needs a real https address — this works once deployed (e.g. on Netlify), not when opened as a local file.</p>\n</div>\n\n<!-- Place picker — shown after sign-in until a place is resolved -->\n<div class=\"signin-screen\" id=\"sitePicker\">\n  <div class=\"semblem\"></div>\n  <h2>Choose your house</h2>\n  <p id=\"sitePickerNote\"></p>\n  <div id=\"sitePickerList\" style=\"width:100%;max-width:320px;margin-top:14px\"></div>\n  <p class=\"signin-note\">Each house keeps its own weekly menu, pantry, grocery list and duties. Recipes stay private to your household.</p>\n  <button class=\"signin-anon\" onclick=\"signOutNow()\" style=\"margin-top:10px\">Sign out</button>\n</div>\n\n<!-- Mandatory name gate — shown after sign-in if the member has no real name yet -->\n<div class=\"signin-screen\" id=\"nameGate\">\n  <div class=\"semblem\"></div>\n  <h2>What's your name?</h2>\n  <p>Welcome ✓ Before you start, tell your family who you are. This name shows on cleaning duties, grocery ticks, and everywhere in the app.</p>\n  <div class=\"email-panel open\" style=\"max-width:320px\">\n    <input type=\"text\" id=\"gateNameInput\" placeholder=\"Your full name\" maxlength=\"30\" autocomplete=\"name\" autocapitalize=\"words\" onkeydown=\"if(event.key==='Enter')submitNameGate()\">\n    <button class=\"btn primary block\" onclick=\"submitNameGate()\"><span>Continue</span></button>\n    <p class=\"email-errmsg\" id=\"gateNameErr\"></p>\n  </div>\n  <button class=\"signin-anon\" onclick=\"signOutNow()\" style=\"margin-top:10px\">Use a different account</button>\n</div>\n\n<!-- Boot splash -->\n<div class=\"splash app-launch\" id=\"splash\" role=\"status\" aria-label=\"Opening OurHouse\">\n  <img class=\"app-launch-icon\" src=\"/icons/ourhouse-192.png\" alt=\"OurHouse\" width=\"88\" height=\"88\" draggable=\"false\">\n  <span class=\"app-launch-spinner\" aria-hidden=\"true\"></span>\n  <span class=\"app-launch-label\">Opening OurHouse</span>\n</div>\n\n<!-- ===================== HOME ===================== -->\n<div class=\"save-feedback\" id=\"saveFeedback\" role=\"status\" aria-live=\"polite\" aria-atomic=\"true\">\n  <span class=\"save-dot\" aria-hidden=\"true\"></span>\n  <span class=\"save-message\" id=\"saveMessage\"></span>\n  <button id=\"saveReviewBtn\" onclick=\"showPendingReview()\">Review</button>\n</div>\n<div class=\"screen active\" id=\"screen-home\">\n  <div class=\"lheader\" style=\"padding-left:0;padding-right:0\">\n    <div class=\"eyebrow\">\n      <button class=\"hamburger\" onclick=\"openDrawer()\" aria-label=\"Menu\"><span></span><span></span><span></span></button>\n      <span id=\"todayEyebrow\" style=\"flex:1;text-align:center\">MONDAY, JULY 13</span>\n      <button class=\"sevak-fab pressable\" id=\"sevakFab\" onclick=\"openSevakSheet()\" aria-label=\"Open OurHouse assistant\"><span data-icon=\"sparkles\" data-icon-size=\"18\"></span></button>\n      <button class=\"notif-bell\" id=\"notifBell\" onclick=\"openNotifCenter()\" aria-label=\"Notification centre\">🔔<span class=\"notif-badge\" id=\"notifBadge\" style=\"display:none\">0</span></button>\n    </div>\n    <div class=\"roomio-wordmark\">OurHouse</div><h1><span id=\"homeTitle\">OurHouse</span> </h1>\n  </div>\n\n  <div id=\"darshanSlot\"></div>\n\n  <div id=\"rateSlot\"></div>\n  <div id=\"googlePromptSlot\"></div>\n  <div id=\"namePromptSlot\"></div>\n\n  <button class=\"hero pressable\" id=\"heroCard\" onclick=\"goTo('week')\">\n    <span class=\"h-badge\" id=\"heroPeople\">👥 9</span>\n    <span class=\"h-eyebrow\" id=\"heroEyebrow\">Tonight's Dinner</span>\n    <span class=\"h-title\" id=\"heroTitle\">Nothing planned yet</span>\n    <span class=\"h-sub\" id=\"heroSub\">Tap to plan the week</span>\n    <span class=\"h-actions\" id=\"heroActions\"></span>\n  </button>\n\n  <div id=\"intelligenceSlot\"></div>\n  <div id=\"alertSlot\"></div>\n  <div id=\"forecastSlot\"></div>\n  <div id=\"festivalSlot\"></div>\n  <div class=\"home-shortcuts\">\n    <div id=\"sabhaSlot\"></div>\n    <button class=\"home-shortcut plan pressable\" onclick=\"openSuggest()\" aria-label=\"Plan a week with smart suggestions\">\n      <span class=\"hs-top\"><span class=\"hs-icon\">✨</span></span>\n      <span class=\"hs-label\">Meal planning</span>\n      <b>Plan a week</b>\n      <span class=\"hs-sub\" id=\"aiCardSub\">Smart meal suggestions</span>\n      <span class=\"hs-arrow\">›</span>\n    </button>\n  </div>\n  <div id=\"dutiesSlot\"></div>\n\n</div>\n\n<!-- Ambient household intelligence — computed privately in a background\n     worker; Cloudflare AI is invited only when a person asks OurHouse. -->\n<div class=\"sheet\" id=\"sheet-intelligence\">\n  <div class=\"grab\"></div>\n  <div class=\"shead\"><h3><span data-icon=\"sparkles\" data-icon-size=\"19\"></span>House Intelligence</h3><button class=\"btn sm grey\" onclick=\"closeAllSheets()\">Close</button></div>\n  <div class=\"sbody\" id=\"intelligenceBody\"></div>\n</div>\n\n<!-- OurHouse assistant -->\n<div class=\"sheet\" id=\"sheet-sevak\">\n  <div class=\"grab\"></div>\n  <div class=\"shead\"><h3><span data-icon=\"calendar\" data-icon-size=\"19\"></span>OurHouse</h3><button class=\"btn sm grey\" onclick=\"closeAllSheets()\">Close</button></div>\n  <div class=\"sbody\">\n    <div class=\"card\" style=\"padding:13px 15px;margin-bottom:12px;background:linear-gradient(135deg,var(--teal-soft),var(--card))\">\n      <b style=\"display:block;font-size:14px\">Ask naturally. OurHouse can act for you.</b>\n      <span style=\"display:block;font-size:12px;color:var(--ink2);margin-top:3px\">Plan meals, update grocery and pantry, show meal plans, review supplies and open household tools.</span>\n    </div>\n    <div class=\"sevak-mic-row\">\n      <input id=\"sevakInput\" placeholder=\"Ask OurHouse anything…\" autocomplete=\"off\" autocapitalize=\"sentences\" onkeydown=\"if(event.key==='Enter')sevakSubmit()\">\n      <button class=\"sevak-mic-btn\" id=\"sevakMicBtn\" onclick=\"toggleSevakListening()\" aria-label=\"Speak to OurHouse\" style=\"display:none\"><span data-icon=\"mic\" data-icon-size=\"19\"></span></button>\n      <button class=\"btn primary sm\" onclick=\"sevakSubmit()\">Go</button>\n    </div>\n    <p class=\"finehint\" id=\"sevakHint\" style=\"margin:8px 0 0\"></p>\n    <div id=\"sevakLog\" class=\"sevak-log\"></div>\n    <div class=\"klabel\" style=\"margin-top:16px\">Try asking</div>\n    <div class=\"sevak-examples\" id=\"sevakExamples\"></div>\n  </div>\n</div>\n\n<!-- Side drawer navigation -->\n<div class=\"drawer-scrim\" id=\"drawerScrim\" onclick=\"closeDrawer()\"></div>\n<div class=\"drawer\" id=\"drawer\" aria-hidden=\"true\">\n  <div class=\"drawer-head\">\n    <div class=\"drawer-brand\">\n      <img class=\"dh-logo\" src=\"/icons/ourhouse-192.png\" alt=\"OurHouse\" draggable=\"false\" oncontextmenu=\"return false\" ondragstart=\"return false\">\n      <div class=\"drawer-brand-copy\">\n        <h3 id=\"drawerName\">OurHouse</h3>\n        <div class=\"dh-sub\" id=\"drawerSub\">Your household, together</div>\n      </div>\n    </div>\n    <div id=\"placeSwitchWrap\" style=\"display:none;margin-top:11px\">\n      <label class=\"dh-switch-label\">Place</label>\n      <select id=\"placeSwitch\" class=\"dh-switch\" onchange=\"onPlaceSwitchChange(this.value)\"></select>\n    </div>\n  </div>\n  <div class=\"drawer-nav\">\n    <button class=\"drawer-item\" id=\"dnav-home\" onclick=\"drawerGo('home')\"><span class=\"di-ic\" data-icon=\"home\"></span>Home</button>\n    <button class=\"drawer-item\" id=\"dnav-week\" onclick=\"drawerGo('week')\"><span class=\"di-ic\" data-icon=\"calendar\"></span>Week planner</button>\n    <button class=\"drawer-item\" id=\"dnav-grocery\" onclick=\"drawerGo('grocery')\"><span class=\"di-ic\" data-icon=\"cart\"></span>Grocery<span class=\"di-badge\" id=\"dnavBadgeGrocery\" style=\"display:none\"></span></button>\n    <button class=\"drawer-item\" id=\"dnav-pantry\" onclick=\"drawerGo('pantry')\"><span class=\"di-ic\" data-icon=\"pantry\"></span>Pantry<span class=\"di-badge\" id=\"dnavBadgePantry\" style=\"display:none\"></span></button>\n    <button class=\"drawer-item\" id=\"dnav-dishes\" onclick=\"drawerGo('dishes')\"><span class=\"di-ic\" data-icon=\"dishes\"></span>Dishes</button>\n    <div class=\"drawer-sep\"></div>\n    <button class=\"drawer-item\" onclick=\"closeDrawer();openSabhaSheet()\"><span class=\"di-ic\" data-icon=\"calendar\"></span>Meetup RSVP</button>\n    <button class=\"drawer-item\" onclick=\"closeDrawer();openDutiesSheet()\"><span class=\"di-ic\" data-icon=\"broom\"></span>Cleaning duties</button>\n    <button class=\"drawer-item\" onclick=\"openExpenses()\"><span class=\"di-ic\" data-icon=\"wallet\"></span>Shared expenses</button>\n    <button class=\"drawer-item\" onclick=\"closeDrawer();openWaterBillSheet()\"><span class=\"di-ic\" data-icon=\"droplet\"></span>Water bill splitter</button>\n    <button class=\"drawer-item\" onclick=\"closeDrawer();openNotifCenter()\"><span class=\"di-ic\" data-icon=\"bell\"></span>Notifications</button>\n    <button class=\"drawer-item\" onclick=\"closeDrawer();openIntelligenceSheet()\"><span class=\"di-ic\" data-icon=\"sparkles\"></span>House Intelligence</button>\n    <div class=\"drawer-sep\"></div>\n    <button class=\"drawer-item\" onclick=\"closeDrawer();openSheet('settings')\"><span class=\"di-ic\" data-icon=\"gear\"></span>Settings</button>\n  </div>\n  <div class=\"drawer-foot\"><button class=\"btn sm red\" id=\"syncPending\" aria-label=\"Review pending changes\" style=\"display:none;width:100%;text-align:left\" onclick=\"showPendingReview()\"></button></div>\n  <div class=\"drawer-foot\" id=\"drawerFoot\">OurHouse · Household companion</div>\n</div>\n\n<div class=\"sheet\" id=\"sheet-removedDishes\">\n  <div class=\"grab\"></div>\n  <div class=\"shead\"><h3>Removed dishes</h3><button class=\"btn sm grey\" onclick=\"closeAllSheets()\">Close</button></div>\n  <div class=\"sbody\"><p class=\"finehint\">Restore a dish to the household library with its ingredients and history.</p><div id=\"removedDishesList\"></div></div>\n</div>\n\n<!-- Reviews history sheet -->\n<div class=\"sheet\" id=\"sheet-reviews\">\n  <div class=\"grab\"></div>\n  <div class=\"shead\"><h3><span data-icon=\"star\" data-icon-size=\"19\"></span>Dinner reviews</h3><button class=\"btn sm grey\" onclick=\"closeAllSheets()\">Close</button></div>\n  <div class=\"sbody\" id=\"reviewsSheetBody\"></div>\n</div>\n\n<!-- ===================== WEEK ===================== -->\n<div class=\"screen\" id=\"screen-week\">\n  <div class=\"lheader\" style=\"padding-left:0;padding-right:0\">\n    <div class=\"eyebrow\"><span>Dinner Planner</span></div><h1>Week</h1>\n  </div>\n  <div class=\"weeknav\">\n    <button class=\"navbtn pressable\" onclick=\"shiftWeek(-1)\" aria-label=\"Previous week\">‹</button>\n    <div class=\"wt\"><b id=\"weekTitle\">This Week</b><span id=\"weekRange\"></span></div>\n    <button class=\"navbtn pressable\" onclick=\"shiftWeek(1)\" aria-label=\"Next week\">›</button>\n  </div>\n  <div id=\"ledger\"></div>\n  <div class=\"wactions\">\n    <button class=\"btn violet\" onclick=\"openSuggest()\"><span data-icon=\"sparkles\" data-icon-size=\"17\"></span>Suggest week</button>\n    <button class=\"btn tint\" onclick=\"openImport()\"><span data-icon=\"clipboard\" data-icon-size=\"17\"></span>Paste menu</button>\n    <button class=\"btn grey span2\" onclick=\"copyLastWeek()\">Copy last week</button>\n    <button class=\"btn primary span2\" onclick=\"generateGrocery()\"><span data-icon=\"basket\" data-icon-size=\"17\"></span>Rebuild grocery list</button>\n    <button class=\"wa-btn span2\" onclick=\"shareWeekMenuWA()\" style=\"justify-content:center\">\n      <svg width=\"16\" height=\"16\" viewBox=\"0 0 32 32\" fill=\"currentColor\"><path d=\"M16 0C7.163 0 0 7.163 0 16c0 2.822.736 5.471 2.027 7.774L0 32l8.469-2.22A15.94 15.94 0 0016 32c8.837 0 16-7.163 16-16S24.837 0 16 0zm0 29.333a13.285 13.285 0 01-6.729-1.822l-.484-.287-5.031 1.319 1.342-4.895-.317-.502A13.25 13.25 0 012.667 16C2.667 8.636 8.636 2.667 16 2.667S29.333 8.636 29.333 16 23.364 29.333 16 29.333zm7.27-9.956c-.398-.199-2.354-1.162-2.719-1.295-.365-.133-.631-.199-.897.199-.266.398-1.029 1.295-1.261 1.561-.232.266-.465.299-.863.1-.398-.2-1.681-.62-3.203-1.977-1.183-1.056-1.982-2.36-2.214-2.758-.232-.398-.025-.613.175-.81.179-.177.398-.465.597-.697.199-.232.266-.398.398-.664.133-.266.067-.498-.033-.697-.1-.199-.897-2.162-1.229-2.96-.323-.776-.651-.671-.897-.683l-.764-.013c-.266 0-.697.1-.1062.498-.365.398-1.394 1.362-1.394 3.324 0 1.962 1.427 3.858 1.626 4.124.199.266 2.809 4.289 6.806 6.015.951.411 1.693.656 2.272.839.955.304 1.824.261 2.511.158.766-.114 2.354-.962 2.686-1.892.332-.93.332-1.727.232-1.892-.099-.166-.365-.266-.763-.465z\"/></svg>\n      Share this week's menu on WhatsApp\n    </button>\n  </div>\n</div>\n\n<!-- ===================== GROCERY ===================== -->\n<div class=\"screen\" id=\"screen-grocery\">\n  <div class=\"lheader\" style=\"padding-left:0;padding-right:0\">\n    <div class=\"eyebrow\"><span>Shopping</span></div><h1>Grocery</h1>\n  </div>\n  <div class=\"addbar\">\n    <input id=\"gAdd\" aria-label=\"Add grocery item\" maxlength=\"180\" placeholder=\"e.g. Rice or 2 kg rice\" oninput=\"previewGroceryQuick()\" onkeydown=\"if(event.key==='Enter')addGroceryQuick()\">\n    <button class=\"btn primary\" onclick=\"addGroceryQuick()\">Add</button>\n    <details class=\"grocery-amount\"><summary>Quantity & unit <span>optional</span></summary><div class=\"gmeasure\">\n      <input id=\"gQuickQty\" type=\"text\" inputmode=\"decimal\" maxlength=\"24\" oninput=\"previewGroceryQuick()\" placeholder=\"e.g. ½\" aria-label=\"Quantity\" onkeydown=\"if(event.key==='Enter')addGroceryQuick()\">\n      <select id=\"gQuickUnit\" aria-label=\"Measuring unit\" onchange=\"previewGroceryQuick()\">\n        <option>pcs</option><option>g</option><option>kg</option><option>ml</option><option>L</option>\n        <option>packet</option><option>bunch</option><option>muthi</option><option>tsp</option><option>tbsp</option><option>cup</option>\n      </select>\n    </div></details><p id=\"gQuickPreview\" class=\"finehint\" role=\"status\">Add a name, or include an amount: 2 kg rice.</p>\n  </div>\n  <div id=\"shopClaimSlot\"></div>\n  <div class=\"scalenote\" id=\"scaleNote\"></div>\n  <div class=\"progress\" id=\"gProgress\"></div>\n  <div class=\"gactions\">\n    <button class=\"wa-btn\" onclick=\"shareGroceryWA()\">\n      <svg width=\"16\" height=\"16\" viewBox=\"0 0 32 32\" fill=\"currentColor\"><path d=\"M16 0C7.163 0 0 7.163 0 16c0 2.822.736 5.471 2.027 7.774L0 32l8.469-2.22A15.94 15.94 0 0016 32c8.837 0 16-7.163 16-16S24.837 0 16 0zm0 29.333a13.285 13.285 0 01-6.729-1.822l-.484-.287-5.031 1.319 1.342-4.895-.317-.502A13.25 13.25 0 012.667 16C2.667 8.636 8.636 2.667 16 2.667S29.333 8.636 29.333 16 23.364 29.333 16 29.333zm7.27-9.956c-.398-.199-2.354-1.162-2.719-1.295-.365-.133-.631-.199-.897.199-.266.398-1.029 1.295-1.261 1.561-.232.266-.465.299-.863.1-.398-.2-1.681-.62-3.203-1.977-1.183-1.056-1.982-2.36-2.214-2.758-.232-.398-.025-.613.175-.81.179-.177.398-.465.597-.697.199-.232.266-.398.398-.664.133-.266.067-.498-.033-.697-.1-.199-.897-2.162-1.229-2.96-.323-.776-.651-.671-.897-.683l-.764-.013c-.266 0-.697.1-.1062.498-.365.398-1.394 1.362-1.394 3.324 0 1.962 1.427 3.858 1.626 4.124.199.266 2.809 4.289 6.806 6.015.951.411 1.693.656 2.272.839.955.304 1.824.261 2.511.158.766-.114 2.354-.962 2.686-1.892.332-.93.332-1.727.232-1.892-.099-.166-.365-.266-.763-.465z\"/></svg>\n      Share on WhatsApp\n    </button>\n    <button class=\"btn sm tint\" onclick=\"openGroceryImport()\"><span data-icon=\"clipboard\" data-icon-size=\"15\"></span>Paste list</button>\n    <button class=\"btn sm green\" id=\"shopTripBtn\" onclick=\"toggleShoppingTrip()\">🛒 I'm going shopping</button>\n    <button class=\"btn sm red\" onclick=\"clearChecked()\">Clear bought</button>\n  </div>\n  <div id=\"groceryList\"></div>\n</div>\n\n<!-- ===================== PANTRY ===================== -->\n<div class=\"screen\" id=\"screen-pantry\">\n  <div class=\"lheader\" style=\"padding-left:0;padding-right:0\">\n    <div class=\"eyebrow\"><span>Household Stock</span></div><h1>Pantry</h1>\n  </div>\n  <div class=\"bigseg\" id=\"pSections\">\n    <button id=\"secKitchen\" class=\"on\" onclick=\"pantrySection='kitchen';pantryFilter='All';haptic();renderPantry()\"><span data-icon=\"dishes\" data-icon-size=\"17\"></span>Kitchen</button>\n    <button id=\"secHousehold\" onclick=\"pantrySection='household';pantryFilter='All';haptic();renderPantry()\"><span data-icon=\"basket\" data-icon-size=\"17\"></span>Household</button>\n  </div>\n  <div class=\"search list-search\"><span style=\"color:var(--label3)\">⌕</span><input id=\"pSearch\" placeholder=\"Search pantry\" oninput=\"renderPantry();keepSearchResultsVisible('pSearch')\"></div>\n  <div class=\"seg\" id=\"pFilters\"></div>\n  <div id=\"pantryActions\"></div>\n  <div class=\"inset\" id=\"pantryList\"></div>\n  <button class=\"btn violet block\" onclick=\"openBarcodeScanner()\"><span data-icon=\"camera\" data-icon-size=\"17\"></span>Scan barcode</button>\n  <div class=\"klabel\" style=\"margin-top:16px\">Import a receipt</div>\n  <label class=\"togglerow\" style=\"gap:12px\"><span>Use receipt AI<small class=\"finehint\" style=\"display:block\">Recommended reader. Cloudflare processes your photo after your first consent. We remember your choice on this device; turn off for on-device reading.</small></span><input type=\"checkbox\" id=\"receiptUseAI\" aria-label=\"Use Cloudflare receipt AI\" onchange=\"chooseReceiptAI()\" checked></label>\n  <div class=\"frow\">\n    <button class=\"btn tint\" style=\"flex:1\" onclick=\"document.getElementById('receiptPhoto').click()\"><span data-icon=\"receipt\" data-icon-size=\"17\"></span>Scan receipt</button>\n    <button class=\"btn tint\" style=\"flex:1\" onclick=\"document.getElementById('receiptGallery').click()\">Upload image</button>\n  </div>\n  <p class=\"finehint\">Scan with your camera or upload a receipt from your photo gallery. Review the items before adding them.</p>\n  <button class=\"btn primary block\" style=\"margin-top:8px\" onclick=\"openPantryEditor(null)\">＋ Add item manually</button>\n  <input type=\"file\" id=\"receiptPhoto\" accept=\"image/*\" capture=\"environment\" style=\"display:none\" onchange=\"openReceiptScan(event)\">\n  <input type=\"file\" id=\"receiptGallery\" accept=\"image/*\" style=\"display:none\" onchange=\"openReceiptScan(event)\">\n</div>\n\n<!-- ===================== DISHES ===================== -->\n<div class=\"screen\" id=\"screen-dishes\">\n  <div class=\"lheader\" style=\"padding-left:0;padding-right:0\">\n    <div class=\"eyebrow\"><span>Your Kitchen Library</span></div><h1>Dishes</h1>\n  </div>\n  <div class=\"search list-search\"><span style=\"color:var(--label3)\">⌕</span><input id=\"dSearch\" placeholder=\"Search dishes\" oninput=\"renderDishes();keepSearchResultsVisible('dSearch')\"></div>\n  <p class=\"finehint\" id=\"recipeDietInfo\"></p>\n  <div id=\"vegetarianReview\" class=\"finehint\" role=\"status\"></div>\n  <div class=\"inset\" id=\"dishList\"></div>\n  <button class=\"btn primary block\" onclick=\"openDishEditor(null)\">＋ New dish</button>\n  <button class=\"btn tint block\" style=\"margin-top:8px\" onclick=\"RoomioRecipes.openImport()\">Import recipe from message or file</button>\n  <button class=\"btn tint block\" style=\"margin-top:8px\" onclick=\"openStarterDishes()\"><span data-icon=\"book\" data-icon-size=\"17\"></span>Add from starter dishes</button>\n  <button class=\"btn grey block\" style=\"margin-top:8px\" onclick=\"openReviewsSheet()\"><span data-icon=\"star\" data-icon-size=\"17\"></span>Dinner reviews</button>\n  <div id=\"removedDishesSlot\"></div>\n  <div id=\"copyDishesSlot\"></div>\n</div>\n\n<!-- ===================== TAB BAR ===================== -->\n<div class=\"tabbar\" role=\"navigation\" aria-label=\"Main sections\">\n  <button class=\"tab on\" id=\"tab-home\" onclick=\"goTo('home')\">\n    <svg viewBox=\"0 0 24 24\"><path d=\"M3.5 10.8 12 3.8l8.5 7\"/><path d=\"M5.5 9.5V20h13V9.5\"/><path d=\"M10 20v-5.5h4V20\"/></svg>Home\n  </button>\n  <button class=\"tab\" id=\"tab-week\" onclick=\"goTo('week')\">\n    <svg viewBox=\"0 0 24 24\"><rect x=\"3.5\" y=\"5\" width=\"17\" height=\"15.5\" rx=\"3.5\"/><path d=\"M3.5 10h17M8.2 2.8v4M15.8 2.8v4\"/></svg>Meals\n  </button>\n  <button class=\"tab\" id=\"tab-grocery\" onclick=\"goTo('grocery')\">\n    <svg viewBox=\"0 0 24 24\"><path d=\"M3 4.5h2.2L7.6 16a2 2 0 0 0 2 1.6h8.2a2 2 0 0 0 2-1.6L21.5 8H6\"/><circle cx=\"10\" cy=\"20.7\" r=\"1.2\"/><circle cx=\"17.6\" cy=\"20.7\" r=\"1.2\"/></svg>Shop\n    <span class=\"badge\" id=\"badgeGrocery\" style=\"display:none\"></span>\n  </button>\n  <button class=\"tab\" id=\"tab-expenses\" onclick=\"openExpenses()\"><span data-icon=\"wallet\" data-icon-size=\"24\"></span>Expenses</button>\n  <button class=\"tab\" id=\"tab-more\" onclick=\"openDrawer()\"><span data-icon=\"gear\" data-icon-size=\"24\"></span>More<span class=\"badge\" id=\"badgePantry\" style=\"display:none\"></span></button>\n</div>\n\n<!-- Duties setup sheet -->\n<div class=\"sheet\" id=\"sheet-duties\">\n  <div class=\"grab\"></div>\n  <div class=\"shead\"><h3><span data-icon=\"broom\" data-icon-size=\"19\"></span>Cleaning duties</h3><button class=\"btn sm grey\" onclick=\"closeAllSheets()\">Close</button></div>\n  <div class=\"sbody\" id=\"dutiesSheetBody\"></div>\n</div>\n\n<!-- Water bill splitter -->\n<div class=\"sheet\" id=\"sheet-waterbill\">\n  <div class=\"grab\"></div>\n  <div class=\"shead\"><h3><span data-icon=\"droplet\" data-icon-size=\"19\"></span>Water bill splitter</h3><button class=\"btn sm grey\" onclick=\"closeAllSheets()\">Close</button></div>\n  <div class=\"sbody\">\n    <div class=\"wb-intro\"><b style=\"color:var(--ink)\">Fair by days stayed</b><br>Enter the four-month bill, then adjust dates only for people who moved in or out during that period.</div>\n    <div class=\"field\"><label>Total bill amount</label><input id=\"wbAmount\" type=\"text\" inputmode=\"decimal\" autocomplete=\"off\" spellcheck=\"false\" maxlength=\"18\" placeholder=\"e.g. 240\" oninput=\"waterInputsChanged()\"></div>\n    <div class=\"wb-period-grid\"><div class=\"field\"><label>Billing period from</label><input id=\"wbStart\" type=\"date\" onchange=\"setWaterPeriod('start',this.value)\"></div>\n      <div class=\"field\"><label>Billing period to</label><input id=\"wbEnd\" type=\"date\" onchange=\"setWaterPeriod('end',this.value)\"></div></div>\n    <div class=\"klabel\" style=\"margin-top:14px\">Add a person</div>\n    <div class=\"addbar\">\n      <input id=\"wbNewPerson\" placeholder=\"Add a person by name…\" maxlength=\"30\" onkeydown=\"if(event.key==='Enter')addWaterPerson()\">\n      <button class=\"btn primary\" onclick=\"addWaterPerson()\">Add</button>\n    </div>\n    <div class=\"klabel\">Who was there, and when?</div>\n    <p class=\"finehint\" style=\"margin:0 0 8px\">Uncheck anyone who wasn’t here at all. Dates default to the full billing period — trim them for anyone who moved in or out partway through.</p>\n    <div class=\"inset\" id=\"wbPeopleList\"></div>\n    <button class=\"btn primary block\" onclick=\"calcWaterSplit()\"><span data-icon=\"calculator\" data-icon-size=\"17\"></span>Calculate fair split</button>\n    <div id=\"wbResults\" style=\"display:none\"></div>\n    <div class=\"klabel\" style=\"margin-top:20px\">Past splits</div>\n    <div class=\"inset\" id=\"wbHistoryList\"></div>\n  </div>\n</div>\n\n<!-- Weekly Meetup RSVP -->\n<div class=\"sheet\" id=\"sheet-sabha\">\n  <div class=\"grab\"></div>\n  <div class=\"shead\"><h3><span data-icon=\"calendar\" data-icon-size=\"19\"></span>Meetup RSVP</h3><button class=\"btn sm grey\" onclick=\"closeAllSheets()\">Close</button></div>\n  <div class=\"sbody\" id=\"sabhaSheetBody\"></div>\n</div>\n\n<!-- Paste a grocery list -->\n<div class=\"sheet\" id=\"sheet-grocery-import\">\n  <div class=\"grab\"></div>\n  <div class=\"shead\"><h3><span data-icon=\"cart\" data-icon-size=\"19\"></span>Paste a grocery list</h3><button class=\"btn sm grey\" onclick=\"closeAllSheets()\">Close</button></div>\n  <div class=\"sbody\">\n    <div class=\"field\">\n      <label>Paste a shopping message — WhatsApp, notes, anything</label>\n      <textarea id=\"groceryImportText\" style=\"min-height:130px\" placeholder=\"e.g.&#10;*Produce:*&#10;Tomatoes - 120&#10;Carrots - 1 bag&#10;*Dairy:*&#10;Butter - 4&#10;Cheese - 17-20 (extra old)\"></textarea>\n    </div>\n    <p class=\"finehint\" style=\"margin:0 0 11px\">Section headings like <b>*Produce:*</b> set the category. Ranges such as <b>2 to 3</b> or <b>17-20</b> use the higher number so you don't under-buy, and anything in brackets is kept as a note.</p>\n    <button class=\"btn primary block\" onclick=\"runGroceryImport()\">Read list</button>\n    <div id=\"groceryImportList\" style=\"margin-top:13px\"></div>\n    <button class=\"btn primary block\" id=\"btnApplyGroceryImport\" style=\"margin-top:6px;display:none\" onclick=\"applyGroceryImport()\">Add to grocery list</button>\n  </div>\n</div>\n\n<!-- Copy dishes between places -->\n<div class=\"sheet\" id=\"sheet-copydishes\">\n  <div class=\"grab\"></div>\n  <div class=\"shead\"><h3><span data-icon=\"swap\" data-icon-size=\"19\"></span>Copy dishes from another place</h3><button class=\"btn sm grey\" onclick=\"closeAllSheets()\">Close</button></div>\n  <div class=\"sbody\">\n    <p class=\"finehint\" style=\"margin:0 0 11px\">Copies the dish list into <b id=\"copyTargetName\">this place</b>. Quantities are stored per-serving, so each dish automatically scales to whatever headcount this house uses \\u2014 including when that changes day to day.</p>\n    <div class=\"field\"><label>Copy from</label><select id=\"copySource\" onchange=\"loadCopySource()\"></select></div>\n    <div id=\"copyPreview\"></div>\n  </div>\n</div>\n\n<!-- Starter dishes -->\n<div class=\"sheet\" id=\"sheet-starter\">\n  <div class=\"grab\"></div>\n  <div class=\"shead\"><h3><span data-icon=\"book\" data-icon-size=\"19\"></span>Starter dishes</h3><button class=\"btn sm grey\" onclick=\"closeAllSheets()\">Close</button></div>\n  <div class=\"sbody\">\n    <p class=\"finehint\" style=\"margin:0 0 11px\">Ready-made dishes with ingredients already filled in. Tick the ones your house cooks and add them all at once — you can edit any of them afterwards.</p>\n    <div class=\"search\" style=\"margin-bottom:10px\"><span style=\"color:var(--label3)\">⌕</span><input id=\"starterSearch\" placeholder=\"Search starter dishes\" oninput=\"renderStarterDishes();keepSearchResultsVisible('starterSearch')\"></div>\n    <div class=\"frow\" style=\"margin-bottom:10px\">\n      <button class=\"btn sm grey\" style=\"flex:1\" onclick=\"selectAllStarters(true)\">Select all</button>\n      <button class=\"btn sm grey\" style=\"flex:1\" onclick=\"selectAllStarters(false)\">Clear</button>\n    </div>\n    <div class=\"inset\" id=\"starterList\"></div>\n    <button class=\"btn primary block\" style=\"margin-top:11px\" id=\"starterAddBtn\" onclick=\"addSelectedStarters()\">Add selected dishes</button>\n  </div>\n</div>\n\n<!-- Notification centre -->\n<div class=\"sheet\" id=\"sheet-notif-center\">\n  <div class=\"grab\"></div>\n  <div class=\"shead\"><h3><span data-icon=\"bell\" data-icon-size=\"19\"></span>Notifications</h3><button class=\"btn sm grey\" onclick=\"closeAllSheets()\">Close</button></div>\n  <div class=\"sbody\" id=\"notifCenterBody\"></div>\n</div>\n\n<!-- ===================== OVERLAYS ===================== -->\n<div class=\"scrim\" id=\"scrim\" onclick=\"closeAllSheets()\"></div>\n<div class=\"sheet\" id=\"sheet-pending\">\n  <div class=\"grab\"></div>\n  <div class=\"shead\"><h3>Changes to sync</h3><button class=\"btn sm grey\" onclick=\"closeAllSheets()\">Close</button></div>\n  <div class=\"sbody\">\n    <p class=\"finehint\">Changes stay on this phone until the shared house confirms them. Review a conflict before applying an older edit over newer work.</p>\n    <div id=\"pendingList\"></div>\n  </div>\n</div>\n\n<!-- Dish picker -->\n<div class=\"sheet\" id=\"sheet-picker\">\n  <div class=\"grab\"></div>\n  <div class=\"shead\"><h3 id=\"pickerTitle\">Choose dinner</h3><button class=\"btn sm grey\" onclick=\"closeAllSheets()\">Done</button></div>\n  <div class=\"sbody\">\n    <div class=\"search\"><span style=\"color:var(--label3)\">⌕</span><input id=\"pickSearch\" placeholder=\"Search or type a new dish…\" oninput=\"renderPicker();keepSearchResultsVisible('pickSearch')\"></div>\n    <div id=\"pickList\"></div>\n  </div>\n</div>\n\n<!-- Suggest week -->\n<div class=\"sheet\" id=\"sheet-suggest\">\n  <div class=\"grab\"></div>\n  <div class=\"shead\"><h3><span data-icon=\"sparkles\" data-icon-size=\"19\"></span>Week suggestions</h3><button class=\"btn sm grey\" onclick=\"closeAllSheets()\">Close</button></div>\n  <div class=\"sbody\">\n    <p class=\"finehint\" style=\"margin:0 0 12px\" id=\"suggestIntro\"></p>\n    <div id=\"suggestList\"></div>\n    <div class=\"frow\" style=\"margin-top:8px\">\n      <button class=\"btn violet\" style=\"flex:1\" id=\"btnResuggest\" onclick=\"runSuggest()\">↻ Suggest again</button>\n      <button class=\"btn primary\" style=\"flex:1.4\" id=\"btnApplySuggest\" onclick=\"applySuggestions()\" disabled>Apply to week</button>\n    </div>\n  </div>\n</div>\n\n<!-- Review dinner -->\n<div class=\"sheet\" id=\"sheet-review\">\n  <div class=\"grab\"></div>\n  <div class=\"shead\"><h3 id=\"reviewTitle\">How was dinner?</h3><button class=\"btn sm grey\" onclick=\"closeAllSheets()\">Skip</button></div>\n  <div class=\"sbody\">\n    <p class=\"finehint\" style=\"margin:0 0 12px\" id=\"reviewSub\"></p>\n    <div class=\"klabel\">How much was left over?</div>\n    <div class=\"ratebtns\" style=\"margin-bottom:16px\" id=\"leftoverBtns\">\n      <button class=\"btn pressable\" onclick=\"pickLeftover('none')\"><em>🍽️</em>None<br><span style=\"font-size:10px;font-weight:500\">all eaten</span></button>\n      <button class=\"btn pressable\" onclick=\"pickLeftover('little')\"><em>🥄</em>A little<br><span style=\"font-size:10px;font-weight:500\">1 portion</span></button>\n      <button class=\"btn pressable\" onclick=\"pickLeftover('some')\"><em>🥣</em>Some<br><span style=\"font-size:10px;font-weight:500\">2-3 portions</span></button>\n      <button class=\"btn pressable\" onclick=\"pickLeftover('lots')\"><em>🍱</em>Lots<br><span style=\"font-size:10px;font-weight:500\">half+ left</span></button>\n    </div>\n    <p class=\"finehint\" id=\"reviewLearnNote\">OurHouse learns from this — next time these dishes are planned, quantities adjust automatically. \"None left\" nudges portions up a little; \"lots left\" nudges them down.</p>\n  </div>\n</div>\n\n<!-- Paste-menu import -->\n<div class=\"sheet\" id=\"sheet-import\">\n  <div class=\"grab\"></div>\n  <div class=\"shead\"><h3><span data-icon=\"clipboard\" data-icon-size=\"19\"></span>Paste a menu</h3><button class=\"btn sm grey\" onclick=\"closeAllSheets()\">Close</button></div>\n  <div class=\"sbody\">\n    <div class=\"field\">\n      <label>Paste any message — WhatsApp, notes, anything</label>\n      <textarea id=\"importText\" style=\"min-height:110px\" placeholder=\"e.g.&#10;Mon – Dal Dhokli&#10;Tuesday: Khichdi + Kadhi&#10;Wed methi thepla, aloo sabzi …\"></textarea>\n    </div>\n    <button class=\"btn primary block\" onclick=\"runImport()\">Parse menu</button>\n    <div id=\"importList\" style=\"margin-top:13px\"></div>\n    <button class=\"btn primary block\" id=\"btnApplyImport\" style=\"margin-top:6px;display:none\" onclick=\"applyImport()\">Apply to this week</button>\n  </div>\n</div>\n\n<!-- Grocery item editor -->\n<div class=\"sheet\" id=\"sheet-groceryedit\">\n  <div class=\"grab\"></div>\n  <div class=\"shead\"><h3>Edit grocery item</h3><button class=\"btn sm grey\" onclick=\"closeAllSheets()\">Cancel</button></div>\n  <div class=\"sbody\">\n    <div class=\"field\"><label>Item name</label><input id=\"gName\"></div>\n    <div class=\"frow\">\n      <div class=\"field\"><label>Quantity</label><input id=\"gQty\" type=\"number\" inputmode=\"decimal\" min=\"0\" step=\"any\" placeholder=\"—\"></div>\n      <div class=\"field\"><label>Unit</label><select id=\"gUnit\"></select></div>\n    </div>\n    <div class=\"field\"><label>Category</label><select id=\"gCat\"></select></div>\n    <div class=\"field\"><label>Where to buy</label><select id=\"gStore\"></select></div>\n    <div class=\"frow\" style=\"margin-top:8px\">\n      <button class=\"btn red\" style=\"flex:1\" onclick=\"deleteGroceryFromEditor()\">Delete</button>\n      <button class=\"btn primary\" style=\"flex:2\" onclick=\"saveGroceryItem()\">Save</button>\n    </div>\n  </div>\n</div>\n\n<!-- Dish editor -->\n<div class=\"sheet\" id=\"sheet-dish\">\n  <div class=\"grab\"></div>\n  <div class=\"shead\"><h3 id=\"dishSheetTitle\">Add recipe</h3><button class=\"btn sm grey\" onclick=\"closeAllSheets()\">Cancel</button></div>\n  <div class=\"sbody\">\n    <div class=\"field dish-name-field\">\n      <label for=\"dName\">Dish name</label>\n      <input id=\"dName\" placeholder=\"e.g. Tomato pasta\" oninput=\"updateDishSuggestions(this.value);RoomioRecipes.search(this.value);checkBanned()\" onblur=\"setTimeout(()=>hideDishSuggestions(),200)\" autocomplete=\"off\">\n      <div class=\"dish-suggest\" id=\"dishSuggest\" style=\"display:none\"></div>\n    </div>\n    <div class=\"dish-suggestion-box\">\n      <label class=\"dish-online-toggle\"><input type=\"checkbox\" id=\"recipeOnlineEnabled\" checked onchange=\"RoomioRecipes.toggle()\"><span id=\"recipeModeLabel\">Find recipe suggestions</span></label>\n      <p class=\"finehint dish-search-hint\">Type a dish name, then choose a suggestion to fill the recipe.</p>\n      <div id=\"recipeOnlineStatus\" role=\"status\" class=\"finehint\" aria-live=\"polite\"></div><div id=\"recipeOnlineResults\"></div>\n      <details class=\"dish-search-privacy\"><summary>About online suggestions</summary><p class=\"finehint\">Dish names are sent to Wikibooks while suggestions are on. Results follow your kitchen mode. Review ingredients before saving. Turn suggestions off to write privately.</p></details>\n    </div>\n    <div class=\"dish-servings\"><label for=\"dServes\">Serves</label><input id=\"dServes\" type=\"number\" inputmode=\"numeric\" min=\"1\" max=\"50\" step=\"1\" aria-describedby=\"dishServingsHelp\"><span>people</span></div>\n    <p class=\"finehint\" id=\"dishServingsHelp\">How many people these ingredient amounts feed.</p>\n    <div class=\"field\"><label>Ingredients</label>\n      <div id=\"ingWarn\" role=\"alert\"></div>\n      <button id=\"recipeAdaptButton\" hidden class=\"btn tint block\" style=\"margin-bottom:12px\" onclick=\"RoomioRecipes.adaptDraft()\">Try substitutions for our kitchen</button>\n      <div id=\"ingRows\"></div>\n      <button class=\"btn sm grey\" onclick=\"addIngRow()\">＋ Add ingredient</button>\n    </div>\n    <details class=\"dish-optional\" id=\"dishMethod\"><summary>Cooking steps <span>optional</span></summary><div class=\"field\"><label class=\"dish-sr-only\" for=\"dInstructions\">Cooking instructions</label><textarea id=\"dInstructions\" oninput=\"checkBanned()\" rows=\"4\" maxlength=\"20000\" placeholder=\"How do you make it?\"></textarea></div></details>\n    <details class=\"dish-optional\" id=\"dishMore\"><summary>Notes & options</summary>\n      <div class=\"field\"><label for=\"dNotes\">Family notes</label><textarea id=\"dNotes\" oninput=\"checkBanned()\" rows=\"3\" maxlength=\"5000\" placeholder=\"Your family’s tips or changes…\"></textarea></div>\n      <div class=\"field\"><label for=\"dEmoji\">Dish icon</label><input id=\"dEmoji\" placeholder=\"Chosen automatically\" maxlength=\"4\"></div>\n      <button class=\"btn grey block\" onclick=\"suggestIngredientsFromTemplate()\">Use a starter ingredient list</button>\n      <p class=\"finehint\">Amounts can be written as ½, 1/2 or 0.5. Review any suggested quantities before saving.</p>\n      <div class=\"field\" id=\"reviewHistWrap\" style=\"display:none\"><label>Past meal feedback</label><div class=\"card\" style=\"padding:4px 13px\" id=\"reviewHist\"></div></div>\n      <button class=\"btn red block\" id=\"dDelete\" onclick=\"deleteDishFromEditor()\">Remove dish</button>\n    </details>\n    <p id=\"dRecipeSource\" class=\"finehint\" style=\"overflow-wrap:anywhere\"></p>\n    <details id=\"recipeShareActions\" class=\"dish-optional\" hidden><summary>Share or export recipe</summary>\n      <p class=\"finehint\">Anyone receiving the exported recipe can read it.</p>\n      <button class=\"btn tint block\" onclick=\"RoomioRecipes.share()\">Share recipe / copy message</button>\n      <div class=\"frow\" style=\"margin-top:8px\"><button class=\"btn grey\" style=\"flex:1\" onclick=\"RoomioRecipes.download('json')\">Export recipe file</button><button class=\"btn grey\" style=\"flex:1\" onclick=\"RoomioRecipes.download('text')\">Download text</button></div>\n      <div id=\"recipeShareFallback\" hidden><label for=\"recipeShareText\">Copy this recipe into your message</label><textarea id=\"recipeShareText\" readonly rows=\"6\"></textarea></div>\n    </details>\n  </div>\n  <div class=\"dish-editor-actions\"><button class=\"btn primary block\" onclick=\"saveDish()\">Save recipe</button></div>\n</div>\n\n<div class=\"sheet\" id=\"sheet-recipe-import\">\n  <div class=\"grab\"></div><div class=\"shead\"><h3>Import a recipe</h3><button class=\"btn sm grey\" onclick=\"closeAllSheets()\">Cancel</button></div>\n  <div class=\"sbody\"><p>Paste a recipe from a message, or open a recipe file. OurHouse prepares an editable draft on this device.</p>\n    <div class=\"field\"><label for=\"recipeImportFile\">Recipe file (.json or .txt, up to 100 KB)</label><input id=\"recipeImportFile\" type=\"file\" accept=\".json,.txt,application/json,text/plain\" onchange=\"RoomioRecipes.file(this)\"></div>\n    <div class=\"field\"><label for=\"recipeImportText\">Recipe message or JSON</label><textarea id=\"recipeImportText\" rows=\"12\" maxlength=\"100000\" placeholder=\"Family dal\nServings: 4\n\nIngredients\n- 1 cup lentils\n- 2 cups water\n\nInstructions\n1. Rinse the lentils.\n2. Simmer until tender.\"></textarea></div>\n    <p class=\"finehint\">For best results include the name, servings, ingredients and instructions. Unstructured text is kept in Notes for you to arrange. Links alone aren’t imported.</p>\n    <p id=\"recipeImportStatus\" role=\"alert\"></p><button class=\"btn primary block\" onclick=\"RoomioRecipes.importDraft()\">Review editable recipe</button>\n  </div>\n</div>\n\n<!-- Pantry editor -->\n<div class=\"sheet\" id=\"sheet-pantryedit\">\n  <div class=\"grab\"></div>\n  <div class=\"shead\"><h3 id=\"pantrySheetTitle\">Add pantry item</h3><button class=\"btn sm grey\" onclick=\"closeAllSheets()\">Cancel</button></div>\n  <div class=\"sbody\">\n    <div class=\"field\"><label>Item name</label><input id=\"pName\" placeholder=\"e.g. Toor Dal\" onchange=\"suggestThresholdUI()\"></div>\n    <div class=\"frow\">\n      <div class=\"field\"><label>Quantity</label><input id=\"pQty\" type=\"number\" inputmode=\"decimal\" min=\"0\" step=\"any\" placeholder=\"0\"></div>\n      <div class=\"field\"><label>Unit</label><select id=\"pUnit\"></select></div>\n    </div>\n    <div class=\"frow\">\n      <div class=\"field\"><label>Low-stock alert below</label><input id=\"pThresh\" type=\"number\" inputmode=\"decimal\" min=\"0\" step=\"any\" placeholder=\"e.g. 0.5\"></div>\n      <div class=\"field\"><label>Category</label><select id=\"pCat\"></select></div>\n    </div>\n    <div class=\"field\"><label>Section</label><select id=\"pSection\">\n      <option value=\"kitchen\"><span data-icon=\"dishes\" data-icon-size=\"17\"></span>Kitchen — food & cooking</option>\n      <option value=\"household\"><span data-icon=\"basket\" data-icon-size=\"17\"></span>Household — cleaning & home</option>\n    </select></div>\n    <p class=\"finehint\" id=\"threshHint\" style=\"display:none\">✨ Suggested a low-stock alert based on how often this kind of item is used.</p>\n    <div class=\"frow\" style=\"margin-top:8px\">\n      <button class=\"btn red\" id=\"pDelete\" style=\"flex:1\" onclick=\"deletePantryFromEditor()\">Delete</button>\n      <button class=\"btn primary\" style=\"flex:2\" onclick=\"savePantryItem()\">Save item</button>\n    </div>\n  </div>\n</div>\n\n<!-- Settings -->\n<div class=\"sheet\" id=\"sheet-settings\">\n  <div class=\"grab\"></div>\n  <div class=\"shead\"><h3>Settings</h3><button class=\"btn sm grey\" onclick=\"closeAllSheets()\">Close</button></div>\n  <div class=\"sbody\">\n    <div class=\"card settings-identity\" id=\"settingsIdentity\" aria-live=\"polite\"></div>\n    <details class=\"settings-group\" id=\"settingsHouseholdGroup\">\n      <summary><span class=\"settings-group-icon\" data-icon=\"home\"></span><span class=\"settings-group-label\"><b>Household</b><small>Family size, kitchen and bills</small></span></summary>\n      <div class=\"settings-group-body\">\n    <div id=\"setHousehold\">\n    <div class=\"card\" style=\"padding:6px 15px;margin-bottom:15px\">\n      <div class=\"togglerow\">\n        <div><b>Family size</b><span>Grocery quantities scale to this by default</span></div>\n        <div class=\"stepper\">\n          <button onclick=\"bumpHousehold(-1)\">−</button>\n          <span class=\"qv\" id=\"hhSize\">4</span>\n          <button onclick=\"bumpHousehold(1)\">＋</button>\n        </div>\n      </div>\n      <div class=\"togglerow\" style=\"border-top:0.5px solid var(--sep)\">\n        <div><b>Vegetarian preferences</b><span>Vegetarian · exclude onion and garlic — filters templates & warns in recipes</span></div>\n        <label class=\"switch\"><input type=\"checkbox\" id=\"sattvikToggle\" onchange=\"dbSet('settings/sattvik', this.checked)\"><span class=\"knob\"></span></label>\n      </div>\n      <div class=\"togglerow\" style=\"border-top:0.5px solid var(--sep)\">\n        <div><b>Auto-build grocery</b><span>Adds new needs live · Rebuild safely cleans outdated auto items</span></div>\n        <label class=\"switch\"><input type=\"checkbox\" id=\"autoGroceryToggle\" onchange=\"dbSet('settings/autoGrocery', this.checked)\"><span class=\"knob\"></span></label>\n      </div>\n      <div class=\"togglerow\" style=\"border-top:0.5px solid var(--sep)\">\n        <div><b>Currency</b><span>Used in bills & spending insights</span></div>\n        <input id=\"currencyInput\" value=\"C$\" maxlength=\"5\" style=\"width:52px;text-align:center;border:none;border-radius:10px;padding:8px 6px;background:var(--fill2);font-size:15px;font-weight:700\" onchange=\"dbSet('settings/currency', this.value.trim()||'C$')\">\n      </div>\n    </div>\n\n    </div>\n    <button class=\"inforow pressable\" id=\"setBills\" onclick=\"openSheet('bills');renderBillsSheet()\"><b>💰 Bill history</b><span class=\"chev\">›</span></button>\n      </div>\n    </details>\n\n    <details class=\"settings-group\" id=\"settingsAlertsGroup\">\n      <summary><span class=\"settings-group-icon\" data-icon=\"bell\"></span><span class=\"settings-group-label\"><b>Alerts & voice</b><small>Notifications and Siri</small></span></summary>\n      <div class=\"settings-group-body\">\n\n    <div class=\"klabel\" style=\"margin-top:15px\">Notifications</div>\n    <div id=\"notifCard\" style=\"margin-bottom:13px\"></div>\n\n    <div class=\"card\" style=\"padding:14px\"><b>Voice assistant</b><p class=\"finehint\">Open OurHouse’s assistant to add groceries or check your meal plan. Voice input is available on supported browsers.</p><button class=\"btn tint block\" onclick=\"openSevakSheet()\">Ask OurHouse</button></div><div id=\"siriPairResult\" hidden></div><div id=\"siriDevices\" hidden></div>\n      </div>\n    </details>\n\n    <details class=\"settings-group\" id=\"settingsPeopleGroup\">\n      <summary><span class=\"settings-group-icon\" data-icon=\"users\"></span><span class=\"settings-group-label\"><b>People & places</b><small>Switch house, invite and manage access</small></span></summary>\n      <div class=\"settings-group-body\">\n        <div id=\"placePanel\"></div>\n        <div id=\"inviteLinkCard\"></div>\n        <div id=\"accessPanel\"></div>\n        <p class=\"finehint\" id=\"settingsRoleNote\" style=\"display:none;margin:0 0 13px;background:var(--fill2);border-radius:12px;padding:11px 13px\"></p>\n      </div>\n    </details>\n\n    <details class=\"settings-group\" id=\"settingsToolsGroup\">\n      <summary><span class=\"settings-group-icon\" data-icon=\"sparkles\"></span><span class=\"settings-group-label\"><b>Tools & help</b><small>Receipt scanning and app guide</small></span></summary>\n      <div class=\"settings-group-body\">\n    <div id=\"setGemini\">\n    <div class=\"klabel\" style=\"margin-top:15px\">AI receipt scanning</div>\n    <div class=\"card\" style=\"padding:6px 15px;margin-bottom:13px\">\n      <div class=\"togglerow\">\n        <div><b>Gemini API key</b><span>Free from aistudio.google.com — enables automatic receipt scanning</span></div>\n      </div>\n      <div class=\"togglerow\" style=\"border-top:0.5px solid var(--sep)\">\n        <input id=\"geminiKeyInput\" type=\"password\" placeholder=\"Paste your key here (AIza…)\" autocomplete=\"off\" autocapitalize=\"off\" style=\"flex:1;border:none;background:var(--fill2);border-radius:10px;padding:9px 12px;font-size:13.5px;font-family:monospace\">\n        <button class=\"btn sm tint\" style=\"margin-left:8px\" onclick=\"saveGeminiKey()\">Save</button>\n      </div>\n      <p class=\"finehint\" style=\"margin:8px 2px 4px\">Without a key, receipt scan falls back to on-device OCR and shows a review screen. With a key, Gemini reads the photo and adds everything to pantry automatically — no tapping needed.</p>\n    </div>\n\n    </div>\n    <button class=\"inforow pressable\" onclick=\"OurHouseGuide.open()\"><b>Interactive user guide</b><span class=\"chev\">›</span></button>\n    <p class=\"finehint\" style=\"margin:7px 2px 13px\">Core household features are free. Family sync, Siri and some scans need internet.</p>\n      </div>\n    </details>\n\n    <details class=\"settings-group\" id=\"settingsDataGroup\">\n      <summary><span class=\"settings-group-icon\" data-icon=\"gear\"></span><span class=\"settings-group-label\"><b>Data & connection</b><small>Sync, backup and setup</small></span></summary>\n      <div class=\"settings-group-body\">\n\n    <div id=\"setSync\">\n    <div class=\"klabel\">Family sync</div>\n    <div class=\"card\" style=\"margin-bottom:13px\" id=\"connStatusCard\"></div>\n\n    <div id=\"setAdvanced\">\n    <button class=\"inforow pressable\" onclick=\"toggleAdvancedSetup()\"><b id=\"advSetupLabel\">Household setup (admin, one-time)</b><span class=\"chev\" id=\"advSetupChev\">›</span></button>\n    <div id=\"advancedSetup\" style=\"display:none\">\n      <p class=\"finehint\" style=\"margin:6px 0 10px\">Only whoever first connects this household to Firebase needs this. Once connected, use “Copy invite link” above to bring in the rest of the family — no pasting for them, ever.</p>\n      <div class=\"field\">\n        <label>Firebase config</label>\n        <textarea class=\"cfg\" id=\"cfgInput\" placeholder='{\"apiKey\":\"…\",\"databaseURL\":\"https://…firebaseio.com\",\"projectId\":\"…\",\"appId\":\"…\"}'></textarea>\n      </div>\n      <button class=\"btn primary block\" onclick=\"saveConfig()\">Save & connect</button>\n    </div>\n    </div>\n    </div>\n\n    <div id=\"setData\">\n    <div class=\"frow\" style=\"margin-top:14px\">\n      <button class=\"btn grey\" style=\"flex:1\" onclick=\"exportData()\">Export backup</button>\n      <button class=\"btn grey\" style=\"flex:1\" onclick=\"document.getElementById('importFile').click()\">Import backup</button>\n    </div>\n    <input type=\"file\" id=\"importFile\" accept=\".json\" style=\"display:none\" onchange=\"importData(event)\">\n    </div>\n    <p class=\"finehint\" style=\"margin-top:14px\" id=\"setFootNote\">Each household keeps its own weekly plan and household data. Recipes stay private to your household. Works the same on iPhone and Android — open this site in the browser and “Add to Home Screen” for an app-like install.</p>\n      </div>\n    </details>\n    </div>\n  </div>\n\n<!-- Special menu / fasting days -->\n<div class=\"sheet\" id=\"sheet-vrat\">\n  <div class=\"grab\"></div>\n  <div class=\"shead\"><h3><span data-icon=\"flame\" data-icon-size=\"19\"></span>Special meal days</h3><button class=\"btn sm grey\" onclick=\"closeAllSheets()\">Close</button></div>\n  <div class=\"sbody\">\n    <p class=\"finehint\" style=\"margin:0 0 12px\">Mark a day when you want a lighter menu. Recipes tagged “Light meal” appear first for that day. You can change the plan at any time.</p>\n    <button class=\"btn primary block\" id=\"vratToggleBtn\" onclick=\"toggleVratToday()\"><span data-icon=\"flame\" data-icon-size=\"17\"></span>Mark today for a special menu</button>\n    <div class=\"klabel\" style=\"margin-top:16px\">Upcoming marked days</div>\n    <div id=\"vratList\"></div>\n  </div>\n</div>\n\n<!-- Barcode scanner -->\n<div class=\"sheet\" id=\"sheet-barcode\">\n  <div class=\"grab\"></div>\n  <div class=\"shead\"><h3><span data-icon=\"camera\" data-icon-size=\"19\"></span>Scan barcode</h3><button class=\"btn sm grey\" onclick=\"closeBarcodeSheet()\">Close</button></div>\n  <div class=\"sbody\">\n    <p class=\"finehint\" style=\"margin:0 0 10px\" id=\"barcodeStatus\">Loading scanner…</p>\n    <div id=\"barcode-reader\" style=\"border-radius:14px;overflow:hidden;background:#000;min-height:180px\"></div>\n    <button class=\"btn tint block\" style=\"margin-top:10px\" onclick=\"document.getElementById('barcodePhoto').click()\"><span data-icon=\"camera\" data-icon-size=\"17\"></span>Or scan from a photo instead</button>\n    <input type=\"file\" id=\"barcodePhoto\" accept=\"image/*\" capture=\"environment\" style=\"display:none\" onchange=\"scanBarcodeFromPhoto(event)\">\n    <div class=\"field\" style=\"margin-top:12px\">\n      <label>Or type the barcode number</label>\n      <div class=\"frow\">\n        <input id=\"barcodeManual\" inputmode=\"numeric\" placeholder=\"e.g. 078742092008\" style=\"flex:2\">\n        <button class=\"btn tint\" style=\"flex:1\" onclick=\"lookupBarcodeManual()\">Look up</button>\n      </div>\n    </div>\n    <div id=\"barcodeProduct\" style=\"display:none;margin-top:6px\">\n      <div class=\"field\"><label>Item name</label><input id=\"bcName\"></div>\n      <div class=\"frow\">\n        <div class=\"field\"><label>Quantity</label><input id=\"bcQty\" type=\"number\" inputmode=\"decimal\" min=\"0\" step=\"any\"></div>\n        <div class=\"field\"><label>Unit</label><select id=\"bcUnit\"></select></div>\n      </div>\n      <div class=\"field\"><label>Section</label><select id=\"bcSection\">\n        <option value=\"kitchen\"><span data-icon=\"dishes\" data-icon-size=\"17\"></span>Kitchen</option><option value=\"household\"><span data-icon=\"basket\" data-icon-size=\"17\"></span>Household</option>\n      </select></div>\n      <button class=\"btn primary block\" onclick=\"addScannedProduct()\">＋ Add to pantry</button>\n    </div>\n  </div>\n</div>\n\n<dialog id=\"receiptConsentDialog\" aria-labelledby=\"receiptConsentTitle\" oncancel=\"event.preventDefault();answerReceiptConsent(false)\" style=\"border-radius:24px;padding:24px;width:min(500px,calc(100vw - 32px))\">\n  <h2 id=\"receiptConsentTitle\">Read receipts with AI?</h2>\n  <p class=\"finehint\" style=\"margin:14px 0\">Cloudflare Workers AI will receive your selected receipt photos to read the products. Photos may contain purchase or personal information. OurHouse does not save the photos or raw scan text on its server for pantry scanning.</p>\n  <p class=\"finehint\" style=\"margin:14px 0\">We’ll remember your choice for this account on this device. You can turn receipt AI off at any time. Every product stays editable before you add it.</p>\n  <button class=\"btn primary block\" onclick=\"answerReceiptConsent(true)\">Agree & use receipt AI</button>\n  <button class=\"btn grey block\" style=\"margin-top:10px\" onclick=\"answerReceiptConsent(false)\">Read on this device</button>\n</dialog>\n<div class=\"sheet\" id=\"sheet-receiptreading\" role=\"dialog\" aria-label=\"Reading receipt\">\n <div class=\"shead\"><h3>Reading your receipt</h3><button class=\"btn sm grey\" onclick=\"stopReceiptReading()\">Cancel</button></div>\n <div class=\"sbody\"><p id=\"receiptReadProgress\" role=\"status\" aria-live=\"polite\"></p><p class=\"finehint\" id=\"receiptReadPrivacy\">You’ll review every item before adding stock.</p></div>\n</div>\n<!-- Scan review (receipt OCR) -->\n<div class=\"sheet\" id=\"sheet-scanreview\">\n  <div class=\"grab\"></div>\n  <div class=\"shead\"><h3><span data-icon=\"receipt\" data-icon-size=\"19\"></span>Scanned items</h3><button class=\"btn sm grey\" onclick=\"closeAllSheets()\">Close</button></div>\n  <div class=\"sbody\">\n    <p class=\"finehint\" style=\"margin:0 0 12px\" id=\"scanReviewIntro\"></p>\n    <div id=\"scanReceiptDetails\" style=\"margin-bottom:16px\"></div>\n    <div id=\"scanReviewList\"></div>\n    <button class=\"btn grey block\" onclick=\"addMissingReceiptItem()\">Add a missing product</button>\n    <button class=\"btn primary block\" style=\"margin-top:6px\" onclick=\"applyScan()\">Add selected to pantry</button>\n  </div>\n</div>\n\n<!-- Monthly insights -->\n<div class=\"sheet\" id=\"sheet-insights\">\n  <div class=\"grab\"></div>\n  <div class=\"shead\"><h3>Kitchen insights</h3><button class=\"btn sm grey\" onclick=\"closeAllSheets()\">Close</button></div>\n  <div class=\"sbody\" id=\"insightsBody\"></div>\n</div>\n\n<div class=\"sheet expense-workspace\" id=\"sheet-expenses\"><div class=\"shead\"><h3 id=\"expensesTitle\">Shared expenses</h3><button class=\"btn sm grey\" onclick=\"closeAllSheets()\">Done</button></div><div class=\"sbody\" id=\"expensesBody\"></div><div class=\"expense-actions\" id=\"expenseActions\"></div><nav class=\"roomio-expense-nav\" aria-label=\"Household sections\"><button onclick=\"leaveExpensesFor('home')\"><span data-icon=\"home\"></span>Home</button><button onclick=\"leaveExpensesFor('week')\"><span data-icon=\"calendar\"></span>Meals</button><button onclick=\"leaveExpensesFor('grocery')\"><span data-icon=\"cart\"></span>Shop</button><button class=\"on\" aria-current=\"page\" onclick=\"selectExpenseGroup(null)\"><span data-icon=\"wallet\"></span>Expenses</button><button onclick=\"closeAllSheets();openDrawer()\"><span data-icon=\"gear\"></span>More</button></nav></div>\n<div class=\"sheet\" id=\"sheet-expenseGroupEditor\"><div class=\"grab\"></div><div class=\"shead\"><h3>Expense group</h3><button class=\"btn sm grey\" onclick=\"openExpenses()\">Back</button></div><div class=\"sbody\" id=\"expenseGroupEditorBody\"></div></div>\n<div class=\"sheet\" id=\"sheet-expenseEditor\"><div class=\"grab\"></div><div class=\"shead\"><button class=\"btn sm grey\" onclick=\"leaveExpenseEditor()\">Cancel</button><h3 id=\"expenseEditorTitle\">Add expense</h3><button class=\"btn sm primary\" id=\"expenseSaveButton\" onclick=\"saveExpenseEntry()\">Save</button></div><div class=\"sbody\" id=\"expenseEditorBody\"></div></div>\n<div class=\"sheet\" id=\"sheet-expenseDetail\"><div class=\"grab\"></div><div class=\"shead\"><h3>Expense details</h3><button class=\"btn sm grey\" onclick=\"openExpenses()\">Back</button></div><div class=\"sbody\" id=\"expenseDetailBody\"></div></div>\n<div class=\"sheet\" id=\"sheet-expenseReview\"><div class=\"grab\"></div><div class=\"shead\"><h3>Review expense save</h3><button class=\"btn sm grey\" onclick=\"showPendingReview()\">Back</button></div><div class=\"sbody\" id=\"expenseReviewBody\"></div></div>\n<div class=\"sheet\" id=\"sheet-expenseReceipt\"><div class=\"shead\"><h3>Receipt</h3><button class=\"btn sm grey\" onclick=\"backFromExpenseReceipt()\">Back</button></div><div class=\"sbody\" id=\"expenseReceiptBody\"></div></div>\n<input id=\"expenseAttachmentInput\" type=\"file\" accept=\"image/*,application/pdf,.pdf\" hidden onchange=\"attachExpenseReceipt(event)\">\n<input id=\"expenseReceiptInput\" type=\"file\" accept=\"image/*\" hidden onchange=\"scanExpenseReceipt(event)\">\n<!-- Bill prompt (after Finish shopping) -->\n<div class=\"sheet\" id=\"sheet-billprompt\">\n  <div class=\"grab\"></div>\n  <div class=\"shead\"><h3><span data-icon=\"wallet\" data-icon-size=\"19\"></span>Log this bill?</h3><button class=\"btn sm grey\" onclick=\"skipBillPrompt()\">Skip</button></div>\n  <div class=\"sbody\">\n    <p class=\"finehint\" style=\"margin:0 0 12px\">Track what this shopping trip cost — totals roll up into weekly, monthly and yearly spending in Insights.</p>\n    <div class=\"field\"><label>Amount spent</label><input id=\"billAmount\" type=\"text\" inputmode=\"decimal\" autocomplete=\"off\" spellcheck=\"false\" maxlength=\"18\" placeholder=\"e.g. 1450\"></div>\n    <div class=\"field\"><label>Note (optional)</label><input id=\"billNote\" placeholder=\"e.g. Weekly vegetables + pantry\"></div>\n    <button class=\"btn primary block\" onclick=\"saveBillPrompt()\">Save bill</button>\n  </div>\n</div>\n\n<!-- Bill history -->\n<div class=\"sheet\" id=\"sheet-bills\">\n  <div class=\"grab\"></div>\n  <div class=\"shead\"><h3><span data-icon=\"wallet\" data-icon-size=\"19\"></span>Bill history</h3><button class=\"btn sm grey\" onclick=\"closeAllSheets()\">Close</button></div>\n  <div class=\"sbody\">\n    <div class=\"field\">\n      <label>Add a bill</label>\n      <div class=\"frow\">\n        <input id=\"manualBillAmount\" type=\"text\" inputmode=\"decimal\" autocomplete=\"off\" spellcheck=\"false\" maxlength=\"18\" placeholder=\"Amount\" style=\"flex:1.3\">\n        <input id=\"manualBillNote\" placeholder=\"Note (optional)\" style=\"flex:1.7\">\n      </div>\n    </div>\n    <button class=\"btn primary block\" onclick=\"addManualBill()\">＋ Add bill</button>\n    <div class=\"klabel\" style=\"margin-top:16px\">All bills</div>\n    <div class=\"inset\" id=\"billList\"></div>\n  </div>\n</div>\n\n<!-- How it works -->\n<div class=\"sheet\" id=\"sheet-howitworks\">\n  <div class=\"grab\"></div>\n  <div class=\"shead\"><h3>How OurHouse thinks</h3><button class=\"btn sm grey\" onclick=\"closeAllSheets()\">Close</button></div>\n  <div class=\"sbody\">\n    <div class=\"howstep\"><div class=\"hn\">1</div><div><b>Grocery = need − stock</b><span>Every dinner's ingredients are scaled to that day's guest count and to what the dish has learned from your reviews, then added up for the week. Whatever's already in your pantry is subtracted — only the shortfall goes on the list.</span></div></div>\n    <div class=\"howstep\"><div class=\"hn\">2</div><div><b>It stays live and safe</b><span>New needs appear automatically. Removing outdated automatic items requires “Rebuild grocery list”, so one phone can never erase groceries another person just added. Bought and hand-added items are always protected.</span></div></div>\n    <div class=\"howstep\"><div class=\"hn\">3</div><div><b>Cooking closes the loop</b><span>“Mark cooked” deducts that dinner's scaled ingredients from the pantry. “Finish shopping” adds bought quantities back in. Stock stays accurate without any manual counting.</span></div></div>\n    <div class=\"howstep\"><div class=\"hn\">4</div><div><b>Smart low-stock defaults</b><span>Condiments like pickle, achaar, chutney, ketchup and jam default to alert at just 1 jar, since they're refilled rarely. Staples like dal, rice and atta get a sensible bulk threshold instead — editable anytime.</span></div></div>\n    <div class=\"howstep\"><div class=\"hn\">5</div><div><b>Scanning is honest about certainty</b><span>Barcode matches from the free Open Food Facts database come pre-selected as <i>clear</i>. Receipt-photo lines the on-device OCR isn't sure about are flagged <i>verify</i> and left unticked, so nothing enters your pantry without your say.</span></div></div>\n    <div class=\"howstep\"><div class=\"hn\">6</div><div><b>Choose special meal days</b><span>Mark days for a lighter menu. Recipes tagged “Light meal” appear first, and your regular library stays available.</span></div></div>\n    <div class=\"howstep\"><div class=\"hn\">7</div><div><b>No paid AI account needed</b><span>Common OurHouse commands run on the phone. More natural requests use the app's shared Cloudflare AI allowance after sign-in, so family members never need to enter or pay for an AI key.</span></div></div>\n    <div class=\"howstep\"><div class=\"hn\">8</div><div><b>Editor & viewer access</b><span>Your Google account keeps the same household and role on every device. New members start as Viewers until an admin promotes them to Editor in Settings.</span></div></div>\n  </div>\n</div>\n\n<!-- Confirm modal -->\n<div class=\"modal\" id=\"confirmModal\">\n  <div class=\"mbox\">\n    <p id=\"confirmMsg\"></p>\n    <div class=\"mrow\">\n      <button class=\"btn grey\" onclick=\"closeConfirm()\">Cancel</button>\n      <button class=\"btn red\" id=\"confirmYes\">Confirm</button>\n    </div>\n  </div>\n</div>\n\n<!-- A reason is required when declining Meetup. It is saved with the RSVP\n     and shown only in the admin response list. -->\n<div class=\"modal\" id=\"sabhaDeclineModal\">\n  <div class=\"mbox\">\n    <h3 style=\"margin:0 0 7px\">Can’t come to Meetup?</h3>\n    <p style=\"margin:0 0 13px;color:var(--ink2);font-size:13.5px;line-height:1.5\">Please add a short reason for the admin.</p>\n    <textarea id=\"sabhaDeclineReason\" maxlength=\"240\" rows=\"4\" placeholder=\"e.g. Working that morning\" oninput=\"updateSabhaReasonCount()\" style=\"width:100%;resize:none;border:0;border-radius:13px;padding:12px 14px;background:var(--fill2)\"></textarea>\n    <div class=\"decline-count\" id=\"sabhaReasonCount\">0 / 240</div>\n    <div class=\"mrow\" style=\"margin-top:12px\">\n      <button class=\"btn grey\" onclick=\"closeSabhaDecline()\">Cancel</button>\n      <button class=\"btn primary\" onclick=\"submitSabhaDecline()\">Save response</button>\n    </div>\n  </div>\n</div>\n\n<!-- Toast -->\n<div class=\"toast\" id=\"toast\">\n  <span class=\"tmsg\" id=\"toastMsg\"></span>\n  <button class=\"tundo\" id=\"toastUndo\" style=\"display:none\" onclick=\"undoLast()\">UNDO</button>\n</div>\n\n\n\n\n<script defer src=\"/intelligence-worker.js\"></script>\n<script defer src=\"/receipt-scanner.js\"></script>\n<script defer src=\"./expense-ledger.js\"></script>\n<script defer src=\"./expense-input.js\"></script>\n<script defer src=\"./receipt-schema.js\"></script>\n<script defer src=\"./expense-cache.js\"></script>\n<script defer src=\"./expense-receipts.js\"></script>\n<script defer src=\"/ourhouse-auth.js?v=2b8d9b6dc336\"></script><script defer src=\"/ourhouse-app.js?v=1a22d85228ed\"></script><script defer src=\"/ourhouse-sync.js?v=34abefcae6cc\"></script><script defer src=\"/ourhouse-metrics.js?v=7c8c6300cd49\"></script><script defer src=\"/ourhouse-cover.js?v=60b953b80398\"></script><script defer src=\"/user-guide.js?v=ec95be610e9d\"></script><script defer src=\"/ourhouse-maintenance.js?v=615fd363ef83\"></script><script defer src=\"/ourhouse-receipts.js?v=419998a37a1a\"></script><script defer src=\"/ourhouse-test.js?v=4d9a8f257a73\"></script><script defer src=\"/roomio-vault.js?v=b4ad60db5922\"></script><script defer src=\"/roomio-recipes.js?v=dde72c58f99c\"></script>\n<script type=\"application/json\" id=\"ourhouse-feature-map\">{\"expenses\":\"/assets/expenses-7e76b0433285c066.js\",\"water\":\"/assets/water-cb1f5a95f71a227f.js\"}</script><script defer src=\"/ourhouse-features.js?v=8193bde96b31\"></script><script defer src=\"/assets/app-core-dd790b030f3c4920.js\"></script>\n</body>\n</html>\n";
